import { Env, json } from "../_shared";

/**
 * The job UUID is generated by Supabase and the manifest is stored in a
 * private R2 key. Avoid GitHub Actions REST API checks here: token scopes
 * and API rate limits can reject valid workflow runs.
 */
export const onRequestGet: PagesFunction<Env> = async ({ request, env }) => {
  const token = request.headers.get("Authorization")?.replace(/^Bearer\s+/i, "").trim() || "";
  const url = new URL(request.url);
  const jobId = url.searchParams.get("job_id") || "";
  const runId = url.searchParams.get("run_id") || "";

  if (!token || !/^\d+$/.test(runId) || !/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(jobId)) {
    return json({ error: "Identitas runner tidak lengkap atau tidak valid." }, 400);
  }

  const object = await env.MEDIA_BUCKET.get(`private-jobs/${jobId}/manifest.json`);
  if (!object) return json({ error: "Manifest job tidak ditemukan." }, 404);

  const manifest = await object.json() as { jobId?: string };
  if (manifest.jobId !== jobId) return json({ error: "Manifest tidak cocok dengan job yang diminta.", requestedJobId: jobId, storedJobId: manifest.jobId || null }, 409);
  return json(manifest);
};
